-- Section 111 — Enlightenment Band 5 Sprint
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den afgørende forskel på Hobbes' og Lockes naturtilstand-analyse — og hvad er den politiske konsekvens af forskellen?","options":["Hobbes: naturtilstanden er en alles krig mod alle der kræver en absolut suveræn for at skabe orden — borgerne har ingen ret til oprør. Locke: naturtilstanden styres af naturlov og rationel respekt for andres rettigheder — regeringen beskytter eksisterende naturlige rettigheder og borgerne har ret til oprør hvis den svigter","Hobbes og Locke er enige om naturtilstandens kaotiske karakter men uenige om suverænitetens juridiske form og borgernes rettigheder","Locke ser naturtilstanden som total kaos og Hobbes ser den som en harmonisk tilstand der ødelægges af det civile samfund","Begge tænkere afviste naturtilstandsbegrebet som et uproduktivt analytisk redskab der ikke bidrager til politisk forståelse"],"correct":"Hobbes: naturtilstanden er en alles krig mod alle der kræver en absolut suveræn for at skabe orden — borgerne har ingen ret til oprør. Locke: naturtilstanden styres af naturlov og rationel respekt for andres rettigheder — regeringen beskytter eksisterende naturlige rettigheder og borgerne har ret til oprør hvis den svigter","accepted_answers":["Hobbes: naturtilstanden er en alles krig mod alle der kræver en absolut suveræn for at skabe orden — borgerne har ingen ret til oprør. Locke: naturtilstanden styres af naturlov og rationel respekt for andres rettigheder — regeringen beskytter eksisterende naturlige rettigheder og borgerne har ret til oprør hvis den svigter"],"review_text":"Hobbes' Leviathan (1651) beskriver naturtilstanden som en tilstand af konstant frygt og vold — liv der er ensomt, fattigt, ubehageligt, brutalt og kort. Den eneste løsning er en absolut suveræn som borgerne ikke kan modsige eller afsætte — suverænen kan ikke misligholde kontrakten da den ikke selv er part i den. Lockes Two Treatises of Government (1689) tegner et andet billede: naturloven giver alle mennesker fornuft til at erkende andres rettigheder til liv, frihed og ejendom. Regeringen er et tillidsforhold — den beskytter disse rettigheder og mister legitimitet hvis den krænker dem. Ret til oprør er en logisk konsekvens. Denne forskel er ikke akademisk: den begrunder to vidt forskellige politiske systemer — absolutisme kontra liberalt konstitutionelt demokrati. Lockes tanker inspirerede den amerikanske uafhængighedserklæring (1776) direkte via Jefferson."}$$::jsonb,
  'mc','short',$${"concepts":["Hobbes","Locke","naturtilstand","absolut suverænitet","naturlige rettigheder","ret til oprør"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er paradokset i Rousseaus politiske tænkning — og hvordan hænger 'mennesket er født frit men er overalt i lænker' og generalviljens begreb sammen?","options":["Paradokset er at Rousseau ikke forkaster staten men den forkerte stat: den rigtige sociale kontrakt skaber et fællesskab der realiserer frihed via generalviljen. Men generalviljens begreb indeholder selv en spænding — det kan bruges til at legitimere undertrykkelse i fællesskabets navn, som Robespierre demonstrerede under Rædselsregimet","Rousseau mener at mennesker er ufrie i naturtilstanden og at det civiliserede samfund befrier dem — lænke-metaforen er positiv og beskriver de nødvendige samfundsmæssige bånd","Rousseau afviser staten som institution fuldstændigt og plæderer for anarkisme som den eneste frihedsrealiserende politiske form","Generalvilje og individuel vilje er identiske begreber hos Rousseau — der er ingen spænding i hans politiske system"],"correct":"Paradokset er at Rousseau ikke forkaster staten men den forkerte stat: den rigtige sociale kontrakt skaber et fællesskab der realiserer frihed via generalviljen. Men generalviljens begreb indeholder selv en spænding — det kan bruges til at legitimere undertrykkelse i fællesskabets navn, som Robespierre demonstrerede under Rædselsregimet","accepted_answers":["Paradokset er at Rousseau ikke forkaster staten men den forkerte stat: den rigtige sociale kontrakt skaber et fællesskab der realiserer frihed via generalviljen. Men generalviljens begreb indeholder selv en spænding — det kan bruges til at legitimere undertrykkelse i fællesskabets navn, som Robespierre demonstrerede under Rædselsregimet"],"review_text":"Rousseaus Du Contrat Social (1762) åbner med den berømte sætning: Mennesket er født frit og er overalt i lænker. Rousseau mener ikke vi skal vende tilbage til naturen men at den rigtige sociale kontrakt kan producere en borgerlig frihed der overstiger naturens frihed. Generalvilje (volonté générale) er ikke summen af individuelle ønsker men hvad fællesskabet rationelt ville ville. Benjamin Constant (1819) formulerede kritikken præcist: Rousseaus frihed forstået som kollektiv politisk deltagelse kan bruges til at udslette individets negative frihed. Robespierre brugte generalviljebegrebet til at legitimere Rædselsregimet — den der afviste generalvilje var kontrarevolutionær og dermed kriminel. Rousseaus arv er derfor splittet: en af oplysningens mest radikale demokratiske tænkere og tillige en utilsigtet intellektuel ressource for politisk totalitarisme."}$$::jsonb,
  'mc','short',$${"concepts":["Rousseau","generalvilje","social kontrakt","frihed","Rædselsregime","Constant"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kernen i Kants definition af oplysning — og hvad er den etiske konsekvens af det kategoriske imperativ?","options":["Oplysning er fremgangen ud af selvforskyldt umyndighed: evnen til at bruge sin fornuft uden andres vejledning. Det kategoriske imperativ kræver at man kun handler efter principper man kan ville som universelle love — etikken er deontologisk og begrundet i fornuften alene, ikke i konsekvenser eller følelser","Kant definerer oplysning som den teknologiske og videnskabelige fremgang der frigør mennesket fra naturens begrænsninger og producerer materiel velstand","Det kategoriske imperativ er Kants navn for utilitarisme — den handling er etisk korrekt der maximerer den samlede lykke for flest mulige","Kant mener at religiøs åbenbaring er grundlaget for etik og at fornuften alene ikke kan nå frem til moralske principper"],"correct":"Oplysning er fremgangen ud af selvforskyldt umyndighed: evnen til at bruge sin fornuft uden andres vejledning. Det kategoriske imperativ kræver at man kun handler efter principper man kan ville som universelle love — etikken er deontologisk og begrundet i fornuften alene, ikke i konsekvenser eller følelser","accepted_answers":["Oplysning er fremgangen ud af selvforskyldt umyndighed: evnen til at bruge sin fornuft uden andres vejledning. Det kategoriske imperativ kræver at man kun handler efter principper man kan ville som universelle love — etikken er deontologisk og begrundet i fornuften alene, ikke i konsekvenser eller følelser"],"review_text":"Kants Was ist Aufklärung? (1784) definerer oplysning som Menneskets fremgang ud af sin selvforskyldte umyndighed og formulerer oplysningstanken i to ord: sapere aude — vov at bruge din egen fornuft. Den selvforskyldte umyndighed skyldes ikke mangel på fornuft men mangel på mod til at bruge den uden andres vejledning. Det kategoriske imperativ (Grundlegung zur Metaphysik der Sitten, 1785) er Kants forsøg på at fundere etikken i ren praktisk fornuft: Handl kun efter den maksime ved hvilken du tillige kan ville at den bliver en almen lov. Denne deontologiske etik er et radikalt brud med religiøs moral og utilitarisme — etik begrundet i pligt, ikke i Guds bud eller beregnede konsekvenser. En central formulering er humanitetsprincippet: behandl ethvert menneske som mål i sig selv, aldrig blot som middel — med direkte implikationer for slaveri, kolonialisme og menneskelig værdighed."}$$::jsonb,
  'mc','short',$${"concepts":["Kant","sapere aude","kategorisk imperativ","deontologisk etik","oplysning","umyndighed"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er Montesquieus vigtigste bidrag til politisk tænkning — og hvad er den metodologiske nyhed i hans tilgang?","options":["Montesquieu introducerede en komparativ og empirisk tilgang til politiske systemer: i stedet for at deducere det ideelle styre fra naturret beskrev og sammenlignede han faktiske styreformer og konkluderede at love og institutioner bør tilpasses historiske og geografiske betingelser — og at magtadskillelse er den institutionelle garanti mod tyranni","Montesquieu argumenterede for absolut monarki som det eneste stabile og retfærdige styresystem og afviste demokrati som strukturelt ustabilt","Montesquieu var primært teolog der forsøgte at harmonisere kristendommen med oplysningens filosofi og naturvidenskab","Montesquieus bidrag var rent litterært og stilistisk — hans politiske analyser har ingen metodologisk originalitet ud over elegant prosa"],"correct":"Montesquieu introducerede en komparativ og empirisk tilgang til politiske systemer: i stedet for at deducere det ideelle styre fra naturret beskrev og sammenlignede han faktiske styreformer og konkluderede at love og institutioner bør tilpasses historiske og geografiske betingelser — og at magtadskillelse er den institutionelle garanti mod tyranni","accepted_answers":["Montesquieu introducerede en komparativ og empirisk tilgang til politiske systemer: i stedet for at deducere det ideelle styre fra naturret beskrev og sammenlignede han faktiske styreformer og konkluderede at love og institutioner bør tilpasses historiske og geografiske betingelser — og at magtadskillelse er den institutionelle garanti mod tyranni"],"review_text":"Montesquieus De l'Esprit des Lois (1748) er et metodologisk brud i politisk tænkning: i stedet for at spørge hvad er den bedste regering spørger Montesquieu hvorfor er regeringer som de er. Hans svar er komparativt og empirisk — han analyserer despotiet, monarkiet og republikken ved at studere historiske og samtidige eksempler. Den berømte klimateori (varme klimaer producerer passive folk der egner sig til despotisme) er nu diskrediteret men metodologisk var den innovativ: politiske institutioner forklares ved materielle og historiske betingelser, ikke guddommelig lov eller abstrakt naturret. Magtadskillelsesteorien (lovgivende, udøvende og dømmende magt) er hans varigste bidrag — den informerede USA's forfatning direkte via Madisons Federalist Papers. Montesquieus analytiske historicisme er en forløber for den komparative politiske videnskab."}$$::jsonb,
  'mc','short',$${"concepts":["Montesquieu","magtadskillelse","komparativ metode","De l'Esprit des Lois","empirisk tilgang","Madison"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den afgørende forskel på naturlige rettigheder og positive (lovgivningsskabte) rettigheder — og hvad er styrken og svagheden ved hvert begreb?","options":["Naturlige rettigheder (Locke, Paine): forud for og uafhængige af staten, begrundede i fornuft — staten kan ikke fjerne dem legitimt. Positive rettigheder: skabt og garanteret af stat og lovgivning, kan ændres demokratisk. Styrke ved naturlige rettigheder: giver et kritisk standpunkt over for uretfærdig lovgivning. Svaghed: det er filosofisk uklart hvad der empirisk begrunder dem hvis ikke religion eller metafysik","Positive rettigheder er altid overlegne fordi de er juridisk håndhævelige og naturlige rettigheder er abstrakte og ineffektive redskaber","Naturlige rettigheder og positive rettigheder er identiske begreber med samme indhold og kun terminologisk forskel","Naturlige rettigheder er en videnskabelig kategori der kan verificeres empirisk mens positive rettigheder er rent politiske konstruktioner"],"correct":"Naturlige rettigheder (Locke, Paine): forud for og uafhængige af staten, begrundede i fornuft — staten kan ikke fjerne dem legitimt. Positive rettigheder: skabt og garanteret af stat og lovgivning, kan ændres demokratisk. Styrke ved naturlige rettigheder: giver et kritisk standpunkt over for uretfærdig lovgivning. Svaghed: det er filosofisk uklart hvad der empirisk begrunder dem hvis ikke religion eller metafysik","accepted_answers":["Naturlige rettigheder (Locke, Paine): forud for og uafhængige af staten, begrundede i fornuft — staten kan ikke fjerne dem legitimt. Positive rettigheder: skabt og garanteret af stat og lovgivning, kan ændres demokratisk. Styrke ved naturlige rettigheder: giver et kritisk standpunkt over for uretfærdig lovgivning. Svaghed: det er filosofisk uklart hvad der empirisk begrunder dem hvis ikke religion eller metafysik"],"review_text":"Thomas Paine formulerede i Rights of Man (1791): Man did not enter into society to become worse than he was before — han trådte ind i samfundet for at få sine eksisterende rettigheder bedre sikret. Naturrettighedsbegrebet (Locke, Grotius, Pufendorf) forudsætter at bestemte rettigheder eksisterer uafhængigt af politisk magt og kan bruges til at kritisere enhver stat der krænker dem. Denne kritiske funktion var afgørende i den amerikanske og franske revolution. Problemet: hvad er det epistemiske grundlag? Jeremy Bentham afviste naturrettighedsbegrebet som nonsense upon stilts — rettigheder eksisterer kun i den forstand at de håndhæves af en stat. Positive rettigheder er juridisk håndgribelige men kan demokratisk tilbagekaldes. FN's menneskerettighedserklæring (1948) kombinerer begge traditioner: den fremstiller rettigheder som universelle men baserer dem i statsratifikation."}$$::jsonb,
  'mc','short',$${"concepts":["naturlige rettigheder","positive rettigheder","Locke","Paine","Bentham","epistemisk grundlag"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det fælles og det divergerende i Hobbes', Lockes og Rousseaus sociale kontrakter — og hvad er den politiske implikation af forskellene?","options":["Fælles: alle tre begrunder statens legitimitet i borgernes samtykke frem for tradition eller Gud — en metodologisk revolution. Divergerende: Hobbes producerer absolut suverænitet uden ret til oprør, Locke producerer begrænset regering med ret til oprør ved svigt og Rousseau producerer fællesskabets suverænitet via generalvilje. Tre vidt forskellige politiske systemer fra det samme udgangspunkt","Hobbes, Locke og Rousseau er enige om alle konklusive politiske implikationer — de tre kontrakter er metodologisk og politisk identiske i deres slutresultater","Rousseau afviser den sociale kontrakt som begreb og argumenterer for direkte naturtilstand som det eneste autentiske menneskeliv","Den sociale kontrakt er et rent hypotetisk tankeeksperiment hos alle tre tænkere uden normative implikationer for faktisk politisk organisation"],"correct":"Fælles: alle tre begrunder statens legitimitet i borgernes samtykke frem for tradition eller Gud — en metodologisk revolution. Divergerende: Hobbes producerer absolut suverænitet uden ret til oprør, Locke producerer begrænset regering med ret til oprør ved svigt og Rousseau producerer fællesskabets suverænitet via generalvilje. Tre vidt forskellige politiske systemer fra det samme udgangspunkt","accepted_answers":["Fælles: alle tre begrunder statens legitimitet i borgernes samtykke frem for tradition eller Gud — en metodologisk revolution. Divergerende: Hobbes producerer absolut suverænitet uden ret til oprør, Locke producerer begrænset regering med ret til oprør ved svigt og Rousseau producerer fællesskabets suverænitet via generalvilje. Tre vidt forskellige politiske systemer fra det samme udgangspunkt"],"review_text":"Den kontraktuelle begrundelse for politisk autoritet er en fælles metodologisk revolution: statens legitimitet hviler på borgernes samtykke, ikke på guddommelig ret eller tradition. Men slutprodukterne er radikalt forskellige. Hobbes' kontrakt: borgerne overgiver alle rettigheder til en absolut suveræn for at sikre fred — suverænen er ikke part i kontrakten og kan ikke misligholde den. Lockes kontrakt: en to-trins aftale om et civilt samfund og en specifik regering der kan afsættes. Rousseaus kontrakt: individet underordner sig generalviljen og opnår civil frihed der overstiger naturens frihed — men ingen institutionel beskyttelse mod majoritetens tyranni er indbygget. John Rawls genoplivede kontrakttænkningen i A Theory of Justice (1971) via uvidenhedens slør — et bevis for at kontrakttraditionens metodologi er levende langt ud over 1700-tallets kontekst."}$$::jsonb,
  'mc','short',$${"concepts":["social kontrakt","Hobbes","Locke","Rousseau","suverænitet","Rawls"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er begrænsningen ved oplysningstidens dominerende frihedsbegreb som negativ frihed — og hvad tilføjer begrebet om positiv frihed?","options":["Negativ frihed (frihed fra statslig indblanding) var progressiv i modsætning til absolutismens kontrol men siger intet om borgernes faktiske evne til at realisere frihed — positiv frihed (frihed til at handle meningsfuldt) kræver sociale betingelser som uddannelse, ejendom og sundhed som negativ frihed ikke garanterer. En tigger og en baron er begge juridisk frie til at overnatte under broerne","Negativ frihed er altid tilstrækkelig og positiv frihed er et ideologisk dække for statslig undertrykkelse via paternalisme og social kontrol","Negativ og positiv frihed er identiske begreber der betegner den samme tilstand blot set fra forskellige vinkler","Oplysningens frihedsbegreb var positivt og fokuserede primært på borgernes aktive politiske deltagelse i kollektive beslutninger"],"correct":"Negativ frihed (frihed fra statslig indblanding) var progressiv i modsætning til absolutismens kontrol men siger intet om borgernes faktiske evne til at realisere frihed — positiv frihed (frihed til at handle meningsfuldt) kræver sociale betingelser som uddannelse, ejendom og sundhed som negativ frihed ikke garanterer. En tigger og en baron er begge juridisk frie til at overnatte under broerne","accepted_answers":["Negativ frihed (frihed fra statslig indblanding) var progressiv i modsætning til absolutismens kontrol men siger intet om borgernes faktiske evne til at realisere frihed — positiv frihed (frihed til at handle meningsfuldt) kræver sociale betingelser som uddannelse, ejendom og sundhed som negativ frihed ikke garanterer. En tigger og en baron er begge juridisk frie til at overnatte under broerne"],"review_text":"Isaiah Berlins Two Concepts of Liberty (1958) er den kanoniske analyse. Negativ frihed: fraværet af ekstern tvang. Oplysningstidens liberale tradition (Locke, Mill) privilegerede dette begreb: frihed er primært statsmagtens tilbagetrækning. Problemet som Rousseau og Marx formulerede fra hvert sit standpunkt: en tigger og en baron er begge juridisk frie til at sove under broerne — men kun baronen kan i realiteten vælge det fra. Positiv frihed: evnen til faktisk at realisere sine mål og leve et selvbestemt liv. Wollstonecraft er Enlightenment-tænkeren der tydeligst pegede på dette: kvinders juridiske frihed var meningsløs uden uddannelse og adgang til de sociale betingelser for faktisk frihed. T.H. Greens New Liberalism (1880erne) forsøgte at bringe positiv frihed ind i den liberale tradition. Spændingen er fortsat strukturerende for politisk teori: velfærdsstat vs libertarianisme er denne debats nutidsversion."}$$::jsonb,
  'mc','short',$${"concepts":["negativ frihed","positiv frihed","Berlin","Wollstonecraft","liberalisme","velfærdsstat"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Satte oplysningen demokratiet i gang — eller skabte den snarere de intellektuelle betingelser som demokratiet selv måtte konstruere?","options":["Oplysningen skabte betingelserne snarere end demokratiet direkte: naturretsteorien, folkesuvereniteten og kritikken af absolut kongemagt leverede de intellektuelle ressourcer som de demokratiske revolutioner transformerede til institutioner. Men mange oplysningsfilosoffer var ambivalente over for bredbaseret demokrati og foretrak oplyst despotisme","Oplysningen skabte automatisk og direkte demokrati — sammenhængen er simpel og ubestridt og alle oplysningsfilosoffer var demokrater i moderne forstand","Oplysningen havde ingen politisk effekt da dens ideer forblev akademiske og aldrig påvirkede politiske institutioner eller revolutionære bevægelser","Demokratiet opstod fuldstændigt uafhængigt af oplysningens ideer og sammenhængen er en retrospektiv historiografisk konstruktion"],"correct":"Oplysningen skabte betingelserne snarere end demokratiet direkte: naturretsteorien, folkesuvereniteten og kritikken af absolut kongemagt leverede de intellektuelle ressourcer som de demokratiske revolutioner transformerede til institutioner. Men mange oplysningsfilosoffer var ambivalente over for bredbaseret demokrati og foretrak oplyst despotisme","accepted_answers":["Oplysningen skabte betingelserne snarere end demokratiet direkte: naturretsteorien, folkesuvereniteten og kritikken af absolut kongemagt leverede de intellektuelle ressourcer som de demokratiske revolutioner transformerede til institutioner. Men mange oplysningsfilosoffer var ambivalente over for bredbaseret demokrati og foretrak oplyst despotisme"],"review_text":"Sammenhængen mellem oplysning og demokrati er reel men kompleks. Lockes folkesuværenitetsprincip, Rousseaus volonté générale og Montesquieus magtadskillelse informerede direkte de amerikanske og franske revolutioners institutionelle design. Men oplysningsfilosofferne var sjældent demokrater i moderne forstand. Voltaire beundrede Frederik den Store og Katarina den Store som oplyste despoter. Kant var ambivalent over for direkte politisk deltagelse. Locke udelukkede de ikke-ejendomsbesiddende fra politisk deltagelse. Diderot var tøvende. Oplysningens projekt var primært Vernunft og toleration — ikke nødvendigvis folkesuverænitet og almen stemmeret. De demokratiske konsekvenser var et produkt af revolutionære transformationer af oplysningsidéer snarere end en enkel logisk konsekvens. Idéhistorie og institutionel historie er to adskilte processer med eget."}$$::jsonb,
  'mc','short',$${"concepts":["oplysning og demokrati","folkesuverænitet","oplyst despotisme","Voltaire","institutionel transformation","idéhistorie"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er deismens position — og hvad er dens funktion som intellektuel tredje vej mellem ortodoks kristendom og ateisme?","options":["Deismen accepterer en skabergud der satte universet i gang via naturlovene men derefter ikke intervenerer via mirakler eller åbenbaring. Denne position gav oplysningsfilosofferne mulighed for at afvise klerikalt autoritetsmonopol og mirakelbaseret religiøsitet uden at hævde ateisme der var juridisk og socialt farlig i 1700-tallets Europa","Deisme er blot en moderne betegnelse for agnosticisme — de to begreber er identiske og begge afviser enhver form for gudserkendelse","Deister afviste alle religiøse forestillinger og var i praksis ateister der brugte 'deisme' som kamuflage for at undgå forfølgelse","Deisme er et marginalt fænomen i oplysningen der kun påvirkede en lille akademisk kreds og ingen bredere kulturel eller politisk betydning havde"],"correct":"Deismen accepterer en skabergud der satte universet i gang via naturlovene men derefter ikke intervenerer via mirakler eller åbenbaring. Denne position gav oplysningsfilosofferne mulighed for at afvise klerikalt autoritetsmonopol og mirakelbaseret religiøsitet uden at hævde ateisme der var juridisk og socialt farlig i 1700-tallets Europa","accepted_answers":["Deismen accepterer en skabergud der satte universet i gang via naturlovene men derefter ikke intervenerer via mirakler eller åbenbaring. Denne position gav oplysningsfilosofferne mulighed for at afvise klerikalt autoritetsmonopol og mirakelbaseret religiøsitet uden at hævde ateisme der var juridisk og socialt farlig i 1700-tallets Europa"],"review_text":"Deismen var udbredt i 1700-tallets intellektuelle klasser: Voltaire, Rousseau, Jefferson, Franklin, Paine og sandsynligvis Kant var alle i varierende grad deister. Gudsbegrebet transformeres: fra en personlig, intervenerende Gud til en urmagerskabers rationelle skabergud der satte urværket i gang og lod naturlovene operere uforstyrret. Denne position tjente flere funktioner: (1) den understøttede videnskabens projekt — naturen er lovmæssig, ikke styret af guddommelig vilkårlighed, (2) den gav basis for kritik af klerikalt autoritetsmonopol, og (3) den var intellektuelt respektabel i en tid hvor ateisme var juridisk farlig og socialt risikabel. Humes posthumt udgivne Dialogues Concerning Natural Religion (1779) er den filosofiske afmontage af det deistiske designargument: selv en rationelt begrundet skabertro holder ikke logisk. Deismen illustrerer at oplysning og religion ikke var enkle modsætninger."}$$::jsonb,
  'mc','short',$${"concepts":["deisme","ateisme","klerikal autoritet","naturlov","Hume","religion og fornuft"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det stærkeste argument for religiøs tolerance i oplysningstidens terminologi — og hvad er grænsen for dette argument?","options":["Stærkeste argument (Locke, Voltaire): staten har ingen epistemisk autoritet til at afgøre religiøs sandhed, og religiøs overbevisning er en indre tilstand der ikke kan frembringes ved tvang — tvungen tro er religiøst virkningsløs og politisk destabiliserende. Grænsen: Locke undtog selv katolikker (lojalitet til paven som fremmed suveræn) og ateister (antages ikke at overholde eder) fra tolerance","Religiøs tolerance var udelukkende taktisk begrundet i opgøret med katolsk kirkes magtmonopol og er ikke et princip der kan generaliseres ud over den protestantisk-katolske konflikt","Oplysningstidens tænkere var enige om at religion bør elimineres fuldstændigt fra det offentlige liv og tolerance er blot et mellemstadie til fuldstændig sekularisering","Religiøs tolerance er kun mulig i protestantiske lande og er strukturelt uforenelig med katolsk og ortodoks religiøs tradition"],"correct":"Stærkeste argument (Locke, Voltaire): staten har ingen epistemisk autoritet til at afgøre religiøs sandhed, og religiøs overbevisning er en indre tilstand der ikke kan frembringes ved tvang — tvungen tro er religiøst virkningsløs og politisk destabiliserende. Grænsen: Locke undtog selv katolikker (lojalitet til paven som fremmed suveræn) og ateister (antages ikke at overholde eder) fra tolerance","accepted_answers":["Stærkeste argument (Locke, Voltaire): staten har ingen epistemisk autoritet til at afgøre religiøs sandhed, og religiøs overbevisning er en indre tilstand der ikke kan frembringes ved tvang — tvungen tro er religiøst virkningsløs og politisk destabiliserende. Grænsen: Locke undtog selv katolikker (lojalitet til paven som fremmed suveræn) og ateister (antages ikke at overholde eder) fra tolerance"],"review_text":"John Lockes A Letter Concerning Toleration (1689) er det centrale dokument. Lockes argument har to led: (1) staten har ikke epistemisk kompetence til at afgøre religiøs sandhed — ingen suveræn er bedre positioneret end borgeren til at vide hvad Gud kræver, og (2) religiøs tro er en indre tilstand der ikke kan frembringes ved ydre tvang. Voltaires Traité sur la Tolérance (1763) skrevet i kølvandet på Jean Calas-sagen — en protestant henrettet som konsekvens af religiøst hysteri — er den mest lidenskabelige populære formulering. Grænsen i Lockes argument er historisk vigtig: han undtog katolikker fordi loyalitet til paven var loyalitet til en fremmed suveræn, og ateister fordi de manglede gudsfrygten til at garantere edersbrud. Lockes tolerance er reel men ikke universel. Spørgsmålet om religiøse udtryks grænser i det sekulariserede offentlige rum er fortsat uafklaret."}$$::jsonb,
  'mc','short',$${"concepts":["religiøs tolerance","Locke","Voltaire","epistemisk autoritet","Jean Calas","undtagelser"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var Encyclopédiens politiske og kulturelle funktion ud over det lexikografiske — og hvad gør den til et kerneprojekt i oplysningen?","options":["Encyclopédien (1751-72) organiserede al menneskelig viden under fornuftens og empiriens autoritet fremfor kirkens og traditionens — den demokratiserede adgangen til viden, legitimerede håndværk og videnskab over teologi og fungerede som et subversivt kulturprogram mod det Ancien Régimes autoritetsstruktur","Encyclopédien var udelukkende et kommercielt forlagsprojekt uden ideologisk eller politisk dimension og bør ikke over-fortolkes","Encyclopédien var et projekt der primært ville bevare traditionel kristen viden og styrke den katolske kirkes position som formidler af sandhed","Encyclopédien var et isoleret akademisk projekt der ikke nåede ud over en lille intellektuel elite og producerede ingen kulturel forandring"],"correct":"Encyclopédien (1751-72) organiserede al menneskelig viden under fornuftens og empiriens autoritet fremfor kirkens og traditionens — den demokratiserede adgangen til viden, legitimerede håndværk og videnskab over teologi og fungerede som et subversivt kulturprogram mod det Ancien Régimes autoritetsstruktur","accepted_answers":["Encyclopédien (1751-72) organiserede al menneskelig viden under fornuftens og empiriens autoritet fremfor kirkens og traditionens — den demokratiserede adgangen til viden, legitimerede håndværk og videnskab over teologi og fungerede som et subversivt kulturprogram mod det Ancien Régimes autoritetsstruktur"],"review_text":"Denis Diderot og Jean le Rond d'Alembert redigerede den 28-binds Encyclopédie (1751-72) med bidrag fra Voltaire, Rousseau, Montesquieu og hundredvis af specialister. Dens subversive kraft lå i organiseringen: ved at systematisere viden under fornuftens og erfaringens autoritet fremfor traditionen og kirken udfordrede den den epistemiske grundlagsstatus for alt religiøst og kongeligt autoritetsmonopol. Et konkret eksempel: artiklen om Teologi er betydeligt kortere end artiklen om Møller — håndværk og teknik placeres i centrum af menneskelig viden. Robert Darnton (The Business of Enlightenment) viser at Encyclopédien var bredt distribueret og læst langt ud over den parisiske elite — den nåede provinsborgerskab, handelsstanden og de uddannede lag der ville udgøre revolutionens sociale base. Den er ikke årsagen til revolutionen men et afgørende kulturelt program der ændrede hvad der var legitimt at spørge om."}$$::jsonb,
  'mc','short',$${"concepts":["Encyclopédie","Diderot","d'Alembert","epistemisk autoritet","viden og magt","Darnton"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kernen i Humes skepticisme — og hvad er dens konsekvens for religiøs tro og for videnskabens kausalitetspåstande?","options":["Hume viser at kausalitet ikke er en observerbar kendsgerning men en mental vane: vi ser A efterfulgt af B gentagne gange og slutter at A forårsager B — men den nødvendige forbindelse er et mentalt tillæg, ikke en iagttaget realitet. Konsekvens for religion: mirakelberetninger er epistemisk problematiske. Konsekvens for videnskab: induktionens logiske grundlag er filosofisk usikret","Hume konkluderer at religiøs tro er rationelt fuldt begrundet og at empirisk videnskab kan bevise gudseksistens med sikkerhed","Hume afviser videnskabens empiriske metoder som ugyldige og argumenterer for ren intuitiv erkendelse som det eneste sikre vidensgrundlag","Humes skepticisme er rent teoretisk og har ingen konsekvenser for praktisk etik, religiøs praksis eller videnskabelig metode"],"correct":"Hume viser at kausalitet ikke er en observerbar kendsgerning men en mental vane: vi ser A efterfulgt af B gentagne gange og slutter at A forårsager B — men den nødvendige forbindelse er et mentalt tillæg, ikke en iagttaget realitet. Konsekvens for religion: mirakelberetninger er epistemisk problematiske. Konsekvens for videnskab: induktionens logiske grundlag er filosofisk usikret","accepted_answers":["Hume viser at kausalitet ikke er en observerbar kendsgerning men en mental vane: vi ser A efterfulgt af B gentagne gange og slutter at A forårsager B — men den nødvendige forbindelse er et mentalt tillæg, ikke en iagttaget realitet. Konsekvens for religion: mirakelberetninger er epistemisk problematiske. Konsekvens for videnskab: induktionens logiske grundlag er filosofisk usikret"],"review_text":"David Humes A Treatise of Human Nature (1739-40) og An Enquiry Concerning Human Understanding (1748) er to af filosofihistoriens mest radikale skeptiske analyser. Humes kausalitetskritik: vi observerer billiardkugle A der rammer B og B bevæger sig — men kausaliteten er ikke en observerbar egenskab ved A, det er et mentalt mønster vi projicerer på erfaringen. Kant kaldte dette sit Hume-chok der vakte ham af dogmatisk slummer. Humes analyse af mirakler (Enquiry Section X) konkluderer at ethvert vidnesbyrd om mirakel altid vejer lettere end den universelle erfaring der understøtter naturloven — rationel tro på mirakler er dermed altid ubegrundet. Humes Dialogues Concerning Natural Religion (postumt 1779) afmonterer designargumentet systematisk. Humes induktionsproblem er endnu ikke løst — Karl Poppers falsifikationsprincip forsøgte at undgå det men er selv omdiskuteret."}$$::jsonb,
  'mc','short',$${"concepts":["Hume","kausalitet","induktionsproblem","mirakler","skepticisme","Kant"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den postkoloniale kritiks stærkeste argument mod oplysningstidens universalismepåstand?","options":["Det stærkeste argument er intern inkonsistens: oplysningsfilosofferne proklamerede universelle menneskelige rettigheder og fornuftens lighed men undtog systematisk ikke-europæere, slaver og kvinder fra disse universelle principper — Kant formulerede eksplicitte racehierarkier, Locke ejede aktier i et slaveselskab og den franske Erklæring om Menneskerettigheder gjaldt ikke for Saint-Domingues slaver. Universalismen var selektiv fra starten","Den postkoloniale kritik er politisk motiveret og har ingen metodologisk relevans for forståelsen af oplysningstidens idéhistorie","Oplysningstidens tænkere var konsekvent og universelt anti-kolonialistiske og antislaveri — den postkoloniale kritik er en grov fejlfortolkning af kildematerialet","Universalisme og kolonialisme er to historisk og analytisk adskilte fænomener uden strukturel forbindelse"],"correct":"Det stærkeste argument er intern inkonsistens: oplysningsfilosofferne proklamerede universelle menneskelige rettigheder og fornuftens lighed men undtog systematisk ikke-europæere, slaver og kvinder fra disse universelle principper — Kant formulerede eksplicitte racehierarkier, Locke ejede aktier i et slaveselskab og den franske Erklæring om Menneskerettigheder gjaldt ikke for Saint-Domingues slaver. Universalismen var selektiv fra starten","accepted_answers":["Det stærkeste argument er intern inkonsistens: oplysningsfilosofferne proklamerede universelle menneskelige rettigheder og fornuftens lighed men undtog systematisk ikke-europæere, slaver og kvinder fra disse universelle principper — Kant formulerede eksplicitte racehierarkier, Locke ejede aktier i et slaveselskab og den franske Erklæring om Menneskerettigheder gjaldt ikke for Saint-Domingues slaver. Universalismen var selektiv fra starten"],"review_text":"Dipesh Chakrabartys Provincializing Europe (2000) og Sankar Muthus Enlightenment Against Empire (2003) repræsenterer to sider af debatten. Muthu viser at visse oplysningsfilosoffer (Diderot, Herder, Kant i visse tekster) faktisk kritiserede imperialismen. Men den interne inkonsistens er metodologisk afgørende: de universelle rettigheder gjaldt ikke for Haiti — den franske republik opretholdt slaveriet i Vestindien under hele revolutionsperioden. Kant formulerede eksplicitte racehierarkier i Physical Geography (1802). Lockes Second Treatise begrundede kolonialisering af Amerika ved at argumentere at kun produktivt bearbejdet land giver ejendomsret — en definition der ekskluderede indianernes brugsformer. Universalismens selvmodsigelse er ikke en ekstern kritik påsat efterfølgende men en spænding synlig i samtiden: Toussaint Louverture, Olympe de Gouges og Wollstonecraft påpegede den alle i perioden 1789-1804."}$$::jsonb,
  'mc','short',$${"concepts":["postkolonial kritik","universalisme","Kant","Locke","slaveri","intern inkonsistens"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kernen i Mary Wollstonecrafts kritik i A Vindication of the Rights of Woman — og hvad er dens metodologiske elegance?","options":["Wollstonecrafts argumentation er internt konsistent med oplysningen: hvis alle mennesker har fornuft og fornuftens kapacitet er grundlag for rettigheder og politisk deltagelse — som oplysningsfilosofferne selv hævdede — kræver det logisk at kvinder inkluderes fuldt ud. Det er ikke en ekstern kritik men en indre konsekvensafkrævning af oplysningens egne præmisser","Wollstonecraft afviste oplysningsfilosofien fuldstændigt og argumenterede for kvinders rettigheder på grundlag af en religiøs tradition uden forbindelse til oplysningstænkningen","Wollstonecrafts argument var udelukkende politisk og praktisk og indeholdt ingen filosofisk dimension der kan analyseres i sammenhæng med Rousseau og Locke","Wollstonecrafts kritik var irrelevant for sin samtid og fik ingen direkte virkning på eftertidens kvinde- og lighedsbevægelser"],"correct":"Wollstonecrafts argumentation er internt konsistent med oplysningen: hvis alle mennesker har fornuft og fornuftens kapacitet er grundlag for rettigheder og politisk deltagelse — som oplysningsfilosofferne selv hævdede — kræver det logisk at kvinder inkluderes fuldt ud. Det er ikke en ekstern kritik men en indre konsekvensafkrævning af oplysningens egne præmisser","accepted_answers":["Wollstonecrafts argumentation er internt konsistent med oplysningen: hvis alle mennesker har fornuft og fornuftens kapacitet er grundlag for rettigheder og politisk deltagelse — som oplysningsfilosofferne selv hævdede — kræver det logisk at kvinder inkluderes fuldt ud. Det er ikke en ekstern kritik men en indre konsekvensafkrævning af oplysningens egne præmisser"],"review_text":"Mary Wollstonecrafts A Vindication of the Rights of Woman (1792) er historisk exceptionel i sin argumentation. Wollstonecraft anvender oplysningsfilosofiens egne præmisser mod dens inkonsistenser: hvis Rousseau og andre har ret i at fornuft definerer menneskelig værdighed og politisk kompetence, og hvis kvinder har fornuft — hvilket intet i oplysningen empirisk benægter — er udelukkelsen af kvinder fra uddannelse og politisk deltagelse en intern modsigelse. Hendes kritik rammer Rousseau direkte: Émile (1762) uddanner den mandlige elev til autonomi og fornuftsbaseret selvbestemmelse mens Sophie uddannes til at behage manden. Wollstonecraft viser at denne konsekvens er uforenelig med Rousseaus egne principper om menneskelig frihed. Metodologisk elegance: hun fælder oplysningen med sit eget sværd. Olympe de Gouges Erklæring om kvinde- og borgerindernes rettigheder (1791) er den politiske parallel. Wollstonecraft inspirerede direkte den første feministiske bølge."}$$::jsonb,
  'mc','short',$${"concepts":["Wollstonecraft","feminisme","fornuft og køn","intern kritik","Rousseau","Olympe de Gouges"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kernen i Edmund Burkes konservative kritik af oplysningstidens politiske projekt — og hvad er det stærkeste argument for hans position?","options":["Burke (Reflections on the Revolution in France, 1790): abstrakt fornuft er utilstrækkelig som grundlag for politiske institutioner — tradition, vane og organisk historisk akkumuleret viden sedimenteret i institutioner som parlament og fælles er langt rigere guide til klok styring end geometriske principper om naturrettigheder. Stærkeste argument: Frankrigs erfaring bekræftede hans forudsigelse — abstrakt rationel konstruktion uden historisk forankring producerede Rædselsregimet","Burke afviste alle reformer og argumenterede for at status quo aldrig burde ændres under nogen som helst omstændigheder","Burkes kritik var rent religiøs og havde ingen politisk filosofisk substans ud over forsvar for den anglikanske kirkes position","Burke og Paine var enige om grundprincipperne men uenige om taktikken for at realisere de samme politiske mål"],"correct":"Burke (Reflections on the Revolution in France, 1790): abstrakt fornuft er utilstrækkelig som grundlag for politiske institutioner — tradition, vane og organisk historisk akkumuleret viden sedimenteret i institutioner som parlament og fælles er langt rigere guide til klok styring end geometriske principper om naturrettigheder. Stærkeste argument: Frankrigs erfaring bekræftede hans forudsigelse — abstrakt rationel konstruktion uden historisk forankring producerede Rædselsregimet","accepted_answers":["Burke (Reflections on the Revolution in France, 1790): abstrakt fornuft er utilstrækkelig som grundlag for politiske institutioner — tradition, vane og organisk historisk akkumuleret viden sedimenteret i institutioner som parlament og fælles er langt rigere guide til klok styring end geometriske principper om naturrettigheder. Stærkeste argument: Frankrigs erfaring bekræftede hans forudsigelse — abstrakt rationel konstruktion uden historisk forankring producerede Rædselsregimet"],"review_text":"Edmund Burkes Reflections on the Revolution in France (1790) er den kanoniske formulering af konservativ tænkning som intellektuel tradition. Burkes centrale argument er epistemologisk: menneskelig fornuft er svag og begrænset, og den akkumulerede visdom i historiske institutioner — common law, parlamentarisk skik — repræsenterer generationers erfaring som ingen enkelt generations abstrakte ratio kan overgå. Partnership of the dead, the living and those yet to be born er Burkes formulering af politisk tradition som intergenerationelt ansvar. Thomas Paine svarede i Rights of Man (1791): at forpligte nulevende til fortids beslutninger er at lade de afdøde styre de levende. Burkes forudsigelse om at den franske revolution ville producere tyranni via sin abstrakte universalisme viste sig empirisk indsigtsfuld — men det beviser ikke at hans konservative konklusion er den eneste mulige reaktion på oplysningens risici."}$$::jsonb,
  'mc','short',$${"concepts":["Burke","konservativ kritik","tradition vs fornuft","Paine","Rædselsregime","institutionel visdom"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er Horkheimers og Adornos central tese i Oplysningens Dialektik — og hvad er konsekvensen for forståelsen af oplysningstidens projekt?","options":["Horkheimer og Adorno argumenterer for at oplysningens fornuft indeholder sin egen selvdestruktive logik: instrumental fornuft — fornuft som middel til at beherske natur og mennesker — vender sig mod oplysningens egne frihedsidealer. Konsekvensen: nazi-barbariet og massekultur er ikke modsætninger til oplysningen men produkter af dens interne logik","Oplysningens Dialektik bekræfter fuldt ud oplysningens projekt og argumenterer for at fornuftens fulde realisering vil producere frihed og menneskelig blomstring","Horkheimer og Adorno argumenterer for at religiøs tro er den eneste korrektiv til oplysningens fejl og at sekulariseringen bør omvendes","Frankfurterskolens kritik er irrelevant fordi den er skrevet i en specifik historisk krisesituation og ikke kan generaliseres ud over 1940ernes kontekst"],"correct":"Horkheimer og Adorno argumenterer for at oplysningens fornuft indeholder sin egen selvdestruktive logik: instrumental fornuft — fornuft som middel til at beherske natur og mennesker — vender sig mod oplysningens egne frihedsidealer. Konsekvensen: nazi-barbariet og massekultur er ikke modsætninger til oplysningen men produkter af dens interne logik","accepted_answers":["Horkheimer og Adorno argumenterer for at oplysningens fornuft indeholder sin egen selvdestruktive logik: instrumental fornuft — fornuft som middel til at beherske natur og mennesker — vender sig mod oplysningens egne frihedsidealer. Konsekvensen: nazi-barbariet og massekultur er ikke modsætninger til oplysningen men produkter af dens interne logik"],"review_text":"Theodor W. Adorno og Max Horkheimers Dialektik der Aufklärung (1944, skrevet i Los Angeles-eksil under 2. Verdenskrig) er et af 1900-tallets mest radikale filosofiske opgør med moderniteten. Tesen: oplysningen satte sig som mål at befri menneskene fra mytens magt via fornuft og viden. Men i processen transformerede fornuften sig til instrumental fornuft — fornuft som beregning af midler til givne mål, uden etisk substans. Holocaust-bureaukratiets effektivitet er det mest ekstreme eksempel: rationelt organiseret, teknisk perfektioneret folkemord. Paradokset: oplysningen der ville befri os fra mytens magt, producerede selv en ny myte — videnskabens og fremskridtets autonome autoritet. Jürgen Habermas' The Theory of Communicative Action (1981) er det mest grundige svar: instrumental fornuft er en deformeret form for fornuft men kommunikativ fornuft orienteret mod gensidig forståelse er det realisable oplysningsprojekt."}$$::jsonb,
  'mc','short',$${"concepts":["Horkheimer","Adorno","instrumental fornuft","Frankfurterskolen","Holocaust","Habermas"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er menneskerettighedernes universelle ambition et legitimt globalt projekt — og hvad er den stærkeste kritik af universalismepåstanden?","options":["Menneskerettigheder er et universelt projekt fordi de beskytter mod universelt genkommende former for undertrykkelse — men den stærkeste indvending er ikke simpel kulturrelativisme men en bedre universalisme: de konkrete rettigheder i FN-erklæringen fra 1948 afspejler vestlig konsensus forhandlet uden den globale syd der dengang primært var koloniseret. En mere inklusivt forhandlet universalisme er det rette svar","Menneskerettigheder er et rent europæisk kulturfænomen der ikke kan overføres til andre kulturer og bør ikke forsøges eksporteret globalt","Kulturrelativisme er altid korrekt og menneskerettigheder har ingen universelle aspekter der kan begrunde kritik af praksisser i andre kulturer","FN-erklæringen fra 1948 er filosofisk perfekt og kræver ingen yderligere revisioner eller supplerende perspektiver fra ikke-vestlige traditioner"],"correct":"Menneskerettigheder er et universelt projekt fordi de beskytter mod universelt genkommende former for undertrykkelse — men den stærkeste indvending er ikke simpel kulturrelativisme men en bedre universalisme: de konkrete rettigheder i FN-erklæringen fra 1948 afspejler vestlig konsensus forhandlet uden den globale syd der dengang primært var koloniseret. En mere inklusivt forhandlet universalisme er det rette svar","accepted_answers":["Menneskerettigheder er et universelt projekt fordi de beskytter mod universelt genkommende former for undertrykkelse — men den stærkeste indvending er ikke simpel kulturrelativisme men en bedre universalisme: de konkrete rettigheder i FN-erklæringen fra 1948 afspejler vestlig konsensus forhandlet uden den globale syd der dengang primært var koloniseret. En mere inklusivt forhandlet universalisme er det rette svar"],"review_text":"FN's Universelle Menneskerettighedserklæring (1948) er direkte arving af oplysningstidens naturrettigheds-tradition. Amnesty International, ICC og internationale humanitære interventioner bygger på dens universalitetspåstand. Den stærkeste indvending er ikke simpel kulturrelativisme (som imploderer fordi den ikke kan forbyde tortur i nogen kultur) men en historiografisk og politisk: de asiatiske, afrikanske og latinamerikanske lande der i dag udgør flertallet af FN's medlemmer var i 1948 overvejende under europæisk kolonistyre og deltog ikke i forhandlingen. Jack Donnelly skelner: universalitet i den normative standard for hvad rettigheder bør beskytte kontra universalitet i de konkrete institutionelle implementeringer der bør kontekstualiseres. Amartya Sen (Development as Freedom) argumenterer for at kapabilitetsbaserede menneskerettigheder er kulturelt resonante langt ud over den vestlige tradition. Den bedste position er en forhandlet universalisme."}$$::jsonb,
  'mc','short',$${"concepts":["menneskerettigheder","universalisme","kulturrelativisme","FN 1948","Sen","forhandlet universalisme"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er sekularisme et neutralt politisk princip — eller afspejler det en kulturelt specifik europæisk løsning på en historisk specifik religiøs konflikt?","options":["Sekularisme er ikke neutral: den adskillelse af kirke og stat som Vesteuropa udviklede som løsning på de protestantisk-katolske religionskrige forudsætter et bestemt syn på religion som en privat overbevisning adskilt fra politik — dette er en historisk specifik position der ikke er logisk nødvendig og som er meningsfuld i én kontekst men ikke universelt neutral","Sekularisme er et universelt neutralt princip der kan adopteres af alle politiske systemer uden kulturel forudsætning eller historisk kontekst","Sekularisme og religion er altid uforenelige og sekularisering er det eneste mulige mål for alle moderne stater uanset historisk tradition","Sekularisme er en ren vestlig politisk konstruktion der aldrig kan fungere i nogen kontekst uden for Nordvesteuropa og Nordamerika"],"correct":"Sekularisme er ikke neutral: den adskillelse af kirke og stat som Vesteuropa udviklede som løsning på de protestantisk-katolske religionskrige forudsætter et bestemt syn på religion som en privat overbevisning adskilt fra politik — dette er en historisk specifik position der ikke er logisk nødvendig og som er meningsfuld i én kontekst men ikke universelt neutral","accepted_answers":["Sekularisme er ikke neutral: den adskillelse af kirke og stat som Vesteuropa udviklede som løsning på de protestantisk-katolske religionskrige forudsætter et bestemt syn på religion som en privat overbevisning adskilt fra politik — dette er en historisk specifik position der ikke er logisk nødvendig og som er meningsfuld i én kontekst men ikke universelt neutral"],"review_text":"Talal Asads Formations of the Secular (2003) er den mest indflydelsesrige analyse. Asads argument: sekularisme er ikke blot statens religionsneutrale position men en specifik regulering af religion der forudsætter at religion er en privat trosoverbevisning adskilt fra offentlig fornuft og magt. Dette forudsætter en bestemt forståelse af hvad religion er — en forståelse der passer på protestantisk kristendom men dårligt på islam (der ikke har en analogt adskilt privat-offentlig distinktion), jødedom og hinduisme som i højere grad er praksisfællesskaber end individuelle trosoverbevisninger. De franske laïcité-debatter om hijab-forbud illustrerer problemet: staten der hævder at regulere neutralt regulerer i praksis religiøs praksis der er synlig i det offentlige rum. Jürgen Habermas' post-sekularisme (2001) forsøger at revidere begrebsapparatet: i et post-sekulært samfund bør staten forblive sekulær men borgere må gerne bruge religiøse argumenter i den offentlige debat."}$$::jsonb,
  'mc','short',$${"concepts":["sekularisme","Asad","laïcité","religion og offentlighed","Habermas","post-sekularisme"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Har oplysningstidens tiltro til fornuftens politiske kapacitet vist sig berettiget — og hvad viser det 20. århundredes erfaringer om dette spørgsmål?","options":["Erfaringen er ambivalent: oplysningsbaserede institutioner (retsstater, internationale organisationer, vidensbaseret politik) har produceret reelle forbedringer. Men det 20. århundredes totalitarismer viste at rationelt organiseret statsapparat kan realisere barbariet mere effektivt end irrationel tradition — instrumentel fornuft er ikke identisk med moralsk fornuft. Svaret er ikke at opgive fornuften men at forstå dens grænser og institutionalisere dens kritiske korrektur","Det 20. århundrede beviser at fornuft altid producerer positive resultater og at alle katastrofer skyldtes irrationel tradition og religion, ikke oplysningens projekt","Det 20. århundrede beviser at fornuftens politiske projekt er et komplet fiasko der bør erstattes af tradition, religiøs autoritet og organisk samfundsviden","Oplysningstidens fornuftsbegreb er uændret tilstrækkelig og relevant og kan løse alle politiske og etiske problemer i det 21. århundrede"],"correct":"Erfaringen er ambivalent: oplysningsbaserede institutioner (retsstater, internationale organisationer, vidensbaseret politik) har produceret reelle forbedringer. Men det 20. århundredes totalitarismer viste at rationelt organiseret statsapparat kan realisere barbariet mere effektivt end irrationel tradition — instrumentel fornuft er ikke identisk med moralsk fornuft. Svaret er ikke at opgive fornuften men at forstå dens grænser og institutionalisere dens kritiske korrektur","accepted_answers":["Erfaringen er ambivalent: oplysningsbaserede institutioner (retsstater, internationale organisationer, vidensbaseret politik) har produceret reelle forbedringer. Men det 20. århundredes totalitarismer viste at rationelt organiseret statsapparat kan realisere barbariet mere effektivt end irrationel tradition — instrumentel fornuft er ikke identisk med moralsk fornuft. Svaret er ikke at opgive fornuften men at forstå dens grænser og institutionalisere dens kritiske korrektur"],"review_text":"Max Weber forudsagde jernburet: rationalisering af det moderne samfund producerer effektive institutioner men tømmer dem for mening og substansiel etik. Adorno og Horkheimer viste at Holocaust var ikke et udbrud af irrationalitet men et resultat af rationelt planlagt, bureaukratisk administreret folkemord. Karl Raimund Poppers The Open Society and Its Enemies (1945) forsvarede fornuftens projekt med epistemologisk ydmyghed: vi kan ikke konstruere det perfekte samfund rationelt (utopisk social engineering er farlig) men vi kan gradvist reformere og korrigere via kritisk fornuft og demokratisk kontrol. Poppers piecemeal social engineering er det mest overbevisende svar: oplysningstidens fornuftstillid var naiv i sin optimisme men at erstatte den med irrationel tradition er endnu farligere. Kritisk, fejlbarlig fornuft med institutionaliserede korrektiv — magtadskillelse, pressefrihed, demokratisk kontrol — er stadig det bedste vi har."}$$::jsonb,
  'mc','short',$${"concepts":["fornuftens grænser","Weber","Popper","instrumental fornuft","piecemeal social engineering","totalitarisme"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er oplysningstidens vigtigste aktuelle arv — og hvad er de uløste spændinger i dette arvegods?","options":["Oplysningens vigtigste arv er metodologisk: empirisk undersøgelse, kritisk tænkning og principper om universel menneskelig værdighed er fundamentale for moderne videnskab, demokrati og menneskerettigheder. De uløste spændinger: universalismens inkonsistente inklusion fra starten, spændingen mellem individuel frihed og kollektive problemer og spørgsmålet om fornuftens grænser i etik og politik under sociale mediers ekkokammer-dynamik","Oplysningens arv er komplet realiseret i liberale demokratier og der er ingen væsentlige uløste spændinger tilbage","Oplysningstidens projekt bør forkastes i sin helhed fordi dets fejl og selvmodsigelser er mere betydningsfulde end dets bidrag","Oplysningstidens ideer er historisk interessante men har ingen relevans for de politiske og etiske spørgsmål det 21. århundrede stiller"],"correct":"Oplysningens vigtigste arv er metodologisk: empirisk undersøgelse, kritisk tænkning og principper om universel menneskelig værdighed er fundamentale for moderne videnskab, demokrati og menneskerettigheder. De uløste spændinger: universalismens inkonsistente inklusion fra starten, spændingen mellem individuel frihed og kollektive problemer og spørgsmålet om fornuftens grænser i etik og politik under sociale mediers ekkokammer-dynamik","accepted_answers":["Oplysningens vigtigste arv er metodologisk: empirisk undersøgelse, kritisk tænkning og principper om universel menneskelig værdighed er fundamentale for moderne videnskab, demokrati og menneskerettigheder. De uløste spændinger: universalismens inkonsistente inklusion fra starten, spændingen mellem individuel frihed og kollektive problemer og spørgsmålet om fornuftens grænser i etik og politik under sociale mediers ekkokammer-dynamik"],"review_text":"Steven Pinkers Enlightenment Now (2018) er den mest optimistiske nutidsaccount: videnskab, humanisme, fornuft og fremskridt har produceret historisk enestående forbedringer i levestandard, fred og frihed. Pinkers kritikere (John Gray, Nassim Taleb) peger på at fremskriddet er skrøbeligt og at det 20. århundredes katastrofer afspejler oplysningsprojektets egne modsætninger. De uløste spændinger er reelle og aktive: (1) Universalisme og inklusion — hvem tilhører menneskeheden? Klimaretfærdighed, migration og kolonialismens arv stiller nye versioner af det klassiske spørgsmål. (2) Fornuft og deliberation — sociale medier og algoritmiske ekkokamre underminerer præcis de betingelser for fornuftig offentlig diskussion som Habermas definerede som demokratiets kommunikative forudsætning. (3) Individuel frihed og kollektive problemer — klimakrisen kræver kollektiv handling der begrænser individuelle friheder på en måde der udfordrer liberalismens grundpræmisser. Oplysningens arvegods er ikke museum men aktiv kampplads."}$$::jsonb,
  'mc','short',$${"concepts":["oplysningens arv","Pinker","Gray","ekkokamre","klimakrise","universalisme og inklusion"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"enlightenment"}$$::jsonb,
  'mc_single',5,'auto',true,'enlightenment',9,5
);;
